using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class MorphDeformationOperations : RefCounted
{
    private static void Pair(List<Vector2> first,List<Vector2> last,Vector2 p,Vector2 q){for(int index=0;index<first.Count;index++)if(first[index].DistanceSquaredTo(p)<.000004f||last[index].DistanceSquaredTo(q)<.000004f)return;first.Add(p);last.Add(q);}
    public void append_pair(Godot.Collections.Array<Vector2> first,Godot.Collections.Array<Vector2> last,Vector2 p,Vector2 q){for(int index=0;index<first.Count;index++)if(first[index].DistanceSquaredTo(p)<.000004f||last[index].DistanceSquaredTo(q)<.000004f)return;first.Add(p);last.Add(q);}
    public Settings triangulate(Vector2[] first,Vector2[] last)
    {
        var middle=new Vector2[first.Length];for(int index=0;index<first.Length;index++)middle[index]=first[index].Lerp(last[index],.5f);var best=new Settings();double score=double.PositiveInfinity;foreach(var domain in new[]{middle,first,last}){var indices=Geometry2D.TriangulateDelaunay(domain);if(indices.Length==0)continue;var quality=validate(first,last,indices);double distortion=quality["distortion"].AsDouble();if(quality["valid"].AsBool()&&distortion<score){best=new Settings {["valid"]=true,["uv_a"]=first,["uv_b"]=last,["indices"]=indices,["distortion"]=distortion};score=distortion;}}return best;
    }
    public Settings validate(Vector2[] first,Vector2[] last,int[] indices)
    {
        double distortion=0;Settings Invalid()=>new() {["valid"]=false,["distortion"]=double.PositiveInfinity};for(int index=0;index<indices.Length;index+=3){int p=indices[index],q=indices[index+1],r=indices[index+2];var e=first[q]-first[p];var f=first[r]-first[p];var de=last[q]-last[p]-e;var df=last[r]-last[p]-f;double c0=e.Cross(f),c1=de.Cross(f)+e.Cross(df),c2=de.Cross(df),middle=c0+c1*.5+c2*.25;Settings Failure(string reason){var failed=Invalid();failed["reason"]=reason;failed["a"]=new GArray {first[p],first[q],first[r]};failed["b"]=new GArray {last[p],last[q],last[r]};return failed;}if(Math.Abs(middle)<.000000001)return Failure("middle degenerate");double sign=middle>0?1:-1,minimum=Math.Min(c0*sign,(c0+c1+c2)*sign);if(Math.Abs(c2)>.00000001){double time=-c1/(2*c2);if(time>0&&time<1)minimum=Math.Min(minimum,(c0+c1*time+c2*time*time)*sign);}if(minimum<-.000000005)return Failure("inverted");double scaleA=Math.Max(.000001,e.Length()*f.Length());var edgeB=last[q]-last[p];var edgeC=last[r]-last[p];double scaleB=Math.Max(.000001,edgeB.Length()*edgeC.Length());if(Math.Max(Math.Abs(c0)/scaleA,Math.Abs(c0+c1+c2)/scaleB)<.000001)return Invalid();distortion+=Math.Abs(Math.Log(Math.Max(.000001,Math.Abs(c0+c1+c2))/Math.Max(.000001,Math.Abs(c0))));}return new Settings {["valid"]=true,["distortion"]=distortion/Math.Max(1,indices.Length/3)};
    }
    public Settings prepare(Settings first,Settings last,Vector2[] pinsA,Vector2[] pinsB,Settings settings)
    {
        using var analysis=new MorphAnalysisOperations();string Text(string key,string fallback)=>settings.TryGetValue(key,out var value)?value.AsString():fallback;var matched=analysis.match(first,last,Text("quality","Fast")=="High"?80:48,Text("alignment","Bounds"));var landmarks=analysis.landmarks(first,last);float strength=settings.TryGetValue("preservation",out var preservation)?preservation.AsSingle():.8f;if(Text("strategy","")=="Shape Morph")strength*=.25f;else if(Text("strategy","")=="Guided Morph"&&pinsA.Length>0)strength*=.5f;var sampledA=matched["a"].AsVector2Array();var sampledB=matched["b"].AsVector2Array();var boundsA=first["bounds"].AsRect2();var boundsB=last["bounds"].AsRect2();
        for(int attempt=0;attempt<2;attempt++){var source=new List<Vector2>();var target=new List<Vector2>();for(int index=0;index<pinsA.Length;index++)Pair(source,target,pinsA[index],pinsB[index]);for(int index=0;index<sampledA.Length;index++)Pair(source,target,sampledA[index],sampledB[index]);for(int side=0;side<2;side++){var outline=(side==0?first:last)["contour"].AsVector2Array();var sampled=side==0?sampledA:sampledB;var paired=side==0?sampledB:sampledA;for(int index=0;index<outline.Length;index++){var p=outline[index];var previous=outline[(index+outline.Length-1)%outline.Length];var next=outline[(index+1)%outline.Length];var incoming=(p-previous).Normalized();var outgoing=(next-p).Normalized();if(Math.Min(p.DistanceTo(previous),p.DistanceTo(next))<.025f||incoming.Dot(outgoing)>.6f)continue;float best=float.PositiveInfinity;var q=Vector2.Zero;for(int j=0;j<sampled.Length;j++){int after=(j+1)%sampled.Length;var near=Geometry2D.GetClosestPointToSegment(p,sampled[j],sampled[after]);float gap=p.DistanceSquaredTo(near);if(gap<best){best=gap;float time=sampled[j].DistanceTo(near)/Math.Max(.000001f,sampled[j].DistanceTo(sampled[after]));q=paired[j].Lerp(paired[after],time);}}if(side==0)Pair(source,target,p,q);else Pair(source,target,q,p);}}
            if(attempt==0)foreach(var feature in landmarks){var point=feature["a"].AsVector2();var normalized=(point-boundsA.Position)/boundsA.Size.Max(Vector2.One*.001f);var basis=boundsB.Position+normalized*boundsB.Size;Pair(source,target,point,basis.Lerp(feature["b"].AsVector2(),strength));}foreach(var point in new[]{Vector2.Zero,Vector2.Right,Vector2.One,Vector2.Down})Pair(source,target,point,point);var result=triangulate(source.ToArray(),target.ToArray());if(result.Count>0){result["method"]=pinsA.Length>0?"Guided mesh":"Contour + feature mesh";result["landmarks"]=attempt==0?Variant.From(landmarks):Variant.From(new GArray());result["contour_a"]=sampledA;result["contour_b"]=sampledB;return result;}}
        return new Settings {["valid"]=false,["reason"]="Correspondence would invert or collapse triangles; using stable implicit topology."};
    }
}
